"""Compare two releases against ordinary checkpoints generated by the chained restore test."""

import json
import os
from pathlib import Path
import platform
import re
import subprocess
import sys
import xml.etree.ElementTree as ET

WORK = Path(os.environ["RUNNER_TEMP"]) / "cmd-guest-fixture"
sys.path.insert(0, str(WORK))
import checkpoint_compat as fixture
import tldk_public_inputs as public_inputs

PUBLISHED = "9ee2906f518e1d0f9fd109e9e1feb2812096418b"
PRODUCT = "912702589414e631909e449f5926b66fa6d5a2c1"
CARRIER = os.environ["GITHUB_SHA"]
REPORT = {"published": PUBLISHED, "product": PRODUCT, "carrier": CARRIER, "runs": {}, "inputs": [], "verified": False}
RECEIPT = WORK / "result.json"
INPUTS = json.loads((WORK / "inputs.json").read_text())
ATTEMPTED = set()
original_run = fixture.run


def save():
    RECEIPT.write_text(json.dumps(REPORT, indent=2))


def admit(rows):
    rows = [r for r in rows if r[2] not in ATTEMPTED]
    ATTEMPTED.update(r[2] for r in rows)
    flags = []
    for directory, row in public_inputs.seed(rows):
        REPORT["inputs"].append(row)
        if directory is not None:
            flags.append("--distdir=" + str(directory))
    fixture.FLAGS.extend(flags)
    save()
    return flags


def run(name, args):
    args = list(args)
    for attempt in range(7):
        code, log = original_run(name, args)
        if not code:
            return code, log
        lines = log.read_text(errors="replace").splitlines()
        # Only recover an actual missing URL from the pinned public catalog.
        failed = "\n".join(line for line in lines if "Error downloading" in line)
        bep_flags = [arg.split("=", 1)[1] for arg in args if arg.startswith("--build_event_json_file=")]
        executed = any(Path(path).exists() and any("testResult" in json.loads(line).get("id", {}) for line in Path(path).read_text().splitlines() if line.strip()) for path in bep_flags)
        flags = [] if executed else admit(row for row in INPUTS if row[2] in failed)
        REPORT.setdefault("diagnostics", {})[name] = [s[:420] for s in lines if "ERROR:" in s or ".go:" in s][-6:]
        save()
        if not flags or attempt == 6:
            return code, log
        args[-1:-1] = flags

def main():
    assert platform.machine() == "x86_64"
    assert fixture.git("rev-parse", "HEAD^") == PRODUCT
    assert fixture.git("rev-parse", "HEAD^^") == PUBLISHED
    fixture.FLAGS[fixture.FLAGS.index("--config=aarch64")] = "--config=x86_64"
    fixture.run = run
    admit(r for r in INPUTS if r[0] in ("protobuf", "bazel_features", "rules_android", "bazel_skylib"))
    fixture.select(PUBLISHED)
    baseline = REPORT["runs"]["stock_release"] = {}
    fixture.stage_old(baseline)
    save()
    fixture.select(CARRIER)
    label = "//runsc/container:container_test"
    case = "TestCheckpointRestoreCrossEngineChained/systrap/wire_to_graph_to_wire"
    selector = "/".join("^" + part + "$" for part in case.split("/"))
    bep = WORK / "chain.bep"
    args = [*fixture.BAZEL, "test", *fixture.FLAGS, "--strategy=TestRunner=standalone",
            "--nocache_test_results", "--flaky_test_attempts=1", "--test_sharding_strategy=disabled",
            "--test_env=GO_TEST_WRAP_TESTV=1", "--test_env=CGROUPV2=true",
            "--test_timeout=1800", "--test_filter=" + selector, "--test_arg=-test.run=" + selector,
            "--test_arg=-test.count=8", "--test_output=errors", "--build_event_json_file=" + str(bep),
            "--run_under=/usr/bin/python3 -IB " + str(fixture.WRAP) + " under", label]
    code, _ = run("chain", args)
    row = REPORT["runs"]["chain"] = {"exit": code, "owner": label, "case": case}
    save()
    matches = []
    for line in bep.read_text().splitlines():
        event = json.loads(line)
        if event.get("id", {}).get("testResult", {}).get("label") == label and "testResult" in event:
            matches.append(event["testResult"])
    result, = matches
    files = fixture.output_files(label, result)
    row["status"] = result["status"]
    row["strategy"] = result["executionInfo"]["strategy"]
    row["cached"] = result.get("cachedLocally", False)
    row["evidence_sha256"] = {name: fixture.H["digest"](path) for name, path in files.items()}
    log = files["test.log"].read_text(errors="replace")
    pairs = re.findall(r'WIRE_PAIR image=([0-9a-f]{64}) bytes=(\d+) stock="([^"]*)" corrected=([0-9a-f]{64})', log)
    row["checkpoints"] = [dict(image_sha256=image, bytes=int(size), stock=stock, corrected_dump_sha256=corrected)
                          for image, size, stock, corrected in pairs]
    row["restored_passes"] = len(re.findall(r"--- PASS: " + re.escape(case) + r" \(", log))
    row["case_xml"] = [{"name": el.get("name"), "skipped": el.find("skipped") is not None,
                        "failed": el.find("failure") is not None or el.find("error") is not None}
                       for el in ET.parse(files["test.xml"]).iter("testcase")]
    measurements = {}
    for match in re.finditer(r"WIRE_REGIONS (?P<fields>image=[^\n\r]+)", log):
        data = dict(field.split("=", 1) for field in match.group("fields").strip().split())
        image = data.pop("image")
        assert image not in measurements
        region = data.pop("region")
        shade = data.pop("workload_shade")
        assert shade in {"true", "false"}
        measurements[image] = {key: int(value) for key, value in data.items()}
        measurements[image].update(region=region, workload_shade=shade == "true")
    for record in row["checkpoints"]:
        record["regions"] = measurements.get(record["image_sha256"])
    row["matching_stock_failures"] = sum(stock == "error printing state: unreachable" for _, _, stock, _ in pairs)
    row["failure_locations"] = sorted(set(re.findall(r"\b\w+_test\.go:\d+:", log)))[:24]
    if code:
        row["test_diagnostics"] = [l.strip()[:360] for l in log.splitlines()
                                   if "container_save_restore_test.go:" in l or "Traceback" in l or
                                   "AssertionError" in l or "Error running as root:" in l][-12:]
    REPORT["verified"] = (not code and row["status"] == "PASSED" and not row["cached"]
                          and row["strategy"] in {"standalone", "local"} and len(pairs) == 8
                          and row["restored_passes"] == 8 and len(measurements) == 8
                          and set(measurements) == {p[0] for p in pairs})
    save()
    assert REPORT["verified"]


if __name__ == "__main__":
    try:
        main()
    finally:
        save()
